// === Tab: mySketch ===
const NUMBER_OF_PARTICLES = 2000

function setup() {
	const width = windowWidth;
	const height = windowHeight;
	createCanvas(windowWidth, windowHeight);
	background(255);
	stroke(0);

	particles = [...new Array(NUMBER_OF_PARTICLES).keys()].map(_ => new Particle(random(width / 2) + width/4, random(height/2) + height/4))

}

function draw() {
	particles.forEach(particle => {
		particle.update();
		particle.draw();
	})
}

// === Tab: Particle ===
class Particle {

	constructor(x, y) {
		this.pos = createVector(x, y);
		this.updateVectors();
	}

	updateVectors() {
		this.v = createVector(random(5) - 2, random(5) - 2);
	}

	update() {
		this.pos.x = int(this.v.x + this.pos.x)
		this.pos.y = int(this.v.y + this.pos.y)
		this.updateVectors();
	}

	draw() {
		point(this.pos.x, this.pos.y);
	}

}

